local _b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local _lookup = {}
for i = 1, #_b64chars do
    _lookup[_b64chars:sub(i, i)] = i - 1
end

local function _decode(data)
    local out = {}
    local n = 0
    local i = 1

    while i <= #data do
        local c1 = data:sub(i, i)
        local c2 = data:sub(i + 1, i + 1)
        local c3 = data:sub(i + 2, i + 2)
        local c4 = data:sub(i + 3, i + 3)

        local a = _lookup[c1] or 0
        local b = _lookup[c2] or 0
        local c = c3 == "=" and 0 or (_lookup[c3] or 0)
        local d = c4 == "=" and 0 or (_lookup[c4] or 0)

        local triple = a * 262144 + b * 4096 + c * 64 + d

        n = n + 1
        out[n] = string.char(math.floor(triple / 65536) % 256)

        if c3 ~= "=" then
            n = n + 1
            out[n] = string.char(math.floor(triple / 256) % 256)
        end

        if c4 ~= "=" then
            n = n + 1
            out[n] = string.char(triple % 256)
        end

        i = i + 4
    end

    return table.concat(out)
end

local _payload = table.concat(_c)
_c = nil

local _source = _decode(_payload)
_payload = nil
_lookup = nil

local _fn, _err = loadstring(_source)
_source = nil

if not _fn then
    error("Eynch protected loader failed: " .. tostring(_err))
end

return _fn()
